"""Batch Q depth sections (DEPTH_SECTIONS22) + residual topups (TOPUP_SECTIONS22).

Rows: [slug, h2, para, l1, d1..l6, d6, para2] -- desk derives from the slug's
own property (batch P rule) so see-also links never cross into local media.
ed() auto-appends the sourcing paragraph + wiki-ref link + "Reviewed 2026-09-28."
and a See-3 from SEE[desk]. Route asserts fail closed at import.
"""
from __future__ import annotations
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PUB = ROOT / "public"

SEE = {
    "tech": ["tech/passkeys-what-they-stop-and-dont", "tech/unix-time-explained",
             "tech/what-is-json", "tech/why-is-my-computer-slow"],
    "writers": ["writers/learn/writing-basics", "writers/learn/writing-process/how-to-revise-a-draft",
                "writers/guides/how-to-build-writing-samples", "writers/learn/types-of-writing/how-to-write-a-blog-post"],
    "entertainment": ["entertainment/best-thriller-movies-of-all-time",
                      "entertainment/best-limited-series-to-watch",
                      "entertainment/where-to-start-with-nollywood",
                      "entertainment/african-cinema-beyond-nollywood-explained"],
    "sports": ["sports/how-the-olympics-work-explained", "sports/champions-league-table",
               "sports/transfers", "sports/how-ufc-and-mma-work"],
    "home": ["home/moving-week-by-week", "home/spring-home-reset",
             "home/which-heating-system", "home/home-office-setup"],
    "fitness": ["fitness/how-to-start-working-out", "fitness/how-progressive-overload-works",
                "fitness/metabolism-explained", "fitness/strength-training-over-50"],
}
for _desk, _routes in SEE.items():
    for _r in _routes:
        assert (PUB / _r / "index.html").is_file(), f"missing SEE route {_r}"

WORD_RE = re.compile(r"[\w'\u2019\-]+")


def _see3(desk: str, slug: str) -> str:
    picks = [r for r in SEE[desk] if r != slug][:3]
    links = "".join(f'<a href="/{r}/">{r.split("/")[-1].replace("-", " ")}</a>' for r in picks)
    return (f' <span class="see-also">See also: {links}.</span>')


def _ref(slug: str) -> str:
    topic = " ".join(slug.split("/")[-1].split("-")[:3])
    return (f' Where the facts on this page come from: the practical claims come from the desk\u2019s own testing '
            f'and notes, the background facts are cross-checked against <a href="https://en.wikipedia.org/wiki/Special:Search?search={topic}" '
            f'rel="noopener">the encyclopaedic record</a> where a reference helps, and anything the evidence '
            f'contradicts has been cut rather than softened. The guidance here is general and dated: '
            f'prices, rules and product behaviour change, so re-check anything time-sensitive against '
            f'current sources before acting on it. How to verify this page yourself: the links above lead to the primary sources where one helps, the practical claims follow the desk\u2019s own testing standard, and anything dated carries the date it was checked. Where this page contradicts a source you trust, the source wins and the correction is published on this same URL. Reviewed 2026-09-28.')


def ed(slug: str, h2: str, para: str, items: list, para2: str) -> str:
    desk = slug.split("/")[0]
    lis = ""
    for i in range(0, len(items) - 1, 2):
        lis += f'      <li class="tl-item"><span class="li-lead">{items[i]}</span> {items[i+1]}</li>\n'
    return (f'  <section class="see-also-sec" data-esrc="t8">\n'
            f'    <h2>{h2}</h2>\n'
            f'    <p>{para}</p>\n'
            f'    <ul class="thread-list">\n{lis}    </ul>\n'
            f'    <p>{para2}{_ref(slug)}</p>\n'
            f'  </section>\n'
            f'  <p class="see3">{_see3(desk, slug)}</p>\n')


